function lengthOfLongestSubstring(s: string): number {
  // Для каждого символа — индекс его последнего вхождения
  const lastSeen = new Map<string, number>();
  let left = 0; // начало окна без повторов
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    const prev = lastSeen.get(ch);

    // Символ уже есть внутри окна — переносим левую границу сразу за него.
    // Проверка prev >= left важна: старые вхождения левее окна не мешают
    if (prev !== undefined && prev >= left) {
      left = prev + 1;
    }

    lastSeen.set(ch, right);
    best = Math.max(best, right - left + 1);
  }

  return best;
}

// Время: O(n) — один проход
// Память: O(min(n, размер алфавита))
